//! Inputs only; entire expected reports come from actual unchanged old registration.
pub const CASES:&[(&str,&str)]=&[
("bare_write","charge = value"),("not_setter","return"),("parent_publish","charge = value\n..()"),("setter_delegate","set_other()"),("foreign_write","other.charge = value"),("index_write","charge[1] = value"),("increment","charge++"),("prefix_hides_increment","-charge++"),("follow_hides_increment","charge++.field"),("group_keeps_increment","(charge++)[1]"),("local_shadow","var/charge = value"),("member_native_not_owned","charge = value\nother.native_write()"),("native_owned","charge = value\nnative_write()"),("unreachable_publish","charge = value\nif(FALSE)\n    tracked_changed(src, \"charge\")"),("global_named_not_publisher","charge = value\n::set_other()"),("static_scope_discards_arguments","charge = value\n/datum/probe::probe(set_other())"),("group_lvalue_not_name","(charge) = value"),("interpolated_delegate",r#"var/text = "[set_other()]""#),("dynamic_vars_not_named",r#"vars["charge"] = value"#),("both_registrations","charge = value"),("explicit_no_write","return"),("allowed","charge = value"),("exempt","charge = value"),("versions","charge = value"),("verb","charge = value"),("maps","charge = value"),("generated","charge = value")
];
pub fn files(case:&str,body:&str)->Vec<(String,String)>{
 let include=!matches!(case,"explicit_no_write");let explicit=matches!(case,"both_registrations"|"explicit_no_write");
 let mut config=if include{"[lint.auto_tracked.lists]\ninclude=[\"/datum/probe::charge\"]\n".to_owned()}else{String::new()};if case=="exempt"{config.push_str("[lint.setter_publishes]\nexempt_files=[\"code/probe.dm\"]\n");}
 let mut code="#define SETTER(T,v)\n/datum/probe\n    var/charge\n".to_owned();if explicit{code.push_str("SETTER(/datum/probe, charge)\n");}if case=="allowed"{code.push_str("// ALLOW(setter_publishes): independent complete report oracle requires this exact publication waiver\n");}
 let kind=if case=="verb"{"verb"}else{"proc"};let mut setter=format!("/datum/probe/{kind}/set_charge(value, datum/probe/other)\n");for line in body.lines(){setter.push_str("    ");setter.push_str(line);setter.push('\n');}if case=="versions"{setter.push_str("/datum/probe/set_charge(value, datum/probe/other)\n    return\n");}
 let mut rows=Vec::new();let mut dme=String::from("#include \"code/probe.dm\"\n");if case=="maps"{rows.push(("maps/setter.dm".into(),setter));dme.push_str("#include \"maps/setter.dm\"\n");}else if case=="generated"{rows.push(("code/engine/_generated/custom.dm".into(),setter));dme.push_str("#include \"code/engine/_generated/custom.dm\"\n");}else{code.push_str(&setter);}
 rows.push(("code/probe.dm".into(),code));for n in 0..140{let path=format!("code/filler_{n:03}.dm");dme.push_str(&format!("#include \"{path}\"\n"));rows.push((path,format!("/datum/filler_{n:03}\n    var/value_{n}=0\n")));}rows.push(("deepquarry.dme".into(),dme));rows.push(("tools/ci/lint_scopes.toml".into(),config));rows
}
